        .args(args)
        .output()
        .context("Failed to run git")?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout);
        Ok(s.lines().map(|l| l.to_string()).collect())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
