fn run_trim(
    args: &Args,
    base_branches: &[String],
    base_remote_refs: &HashSet<(String, String)>,
    base_commits: &HashSet<String>,
    delete_ranges: &[DeleteRange],
    protected_patterns: &[String],
    local_branches: &[String],
    current_branch: &Option<String>,
    remotes: &[String],
    no_confirm: bool,
    no_detach: bool,
) -> Result<()> {
    let dry_run = args.dry_run;

    // Collect all info
    // Local branch classifications
    enum LocalClass {
        Base,
        BaseStray,  // base but upstream is gone
        Protected(String),  // protected by pattern
        MergedTracking,
        StrayTracking,
        DivergdTracking,
        NonTrackingMerged,
        Other,      // not tracking, not merged, or tracking not merged
    }

    struct LBranchInfo {
        name: String,
        class: LocalClass,
        upstream_remote: Option<String>,
        upstream_branch: Option<String>,
        upstream_ref: Option<String>,
        upstream_exists: bool,
        commit: String,
        upstream_commit: Option<String>,
    }

    let mut lb_infos: Vec<LBranchInfo> = Vec::new();

    for branch in local_branches {
        let is_base = base_branches.contains(branch);
        let commit = get_head_commit(branch).unwrap_or_default();

        let upstream_data = get_branch_upstream(branch);
        let (upstream_remote, upstream_branch, upstream_ref, upstream_exists, upstream_commit) = 
            if let Some((uref, uremote, umerge)) = &upstream_data {
                let ubranch = umerge.strip_prefix("refs/heads/").unwrap_or(umerge).to_string();
                let uexists = remote_ref_exists(uremote, &ubranch);
                let ucommit = if uexists { get_head_commit(uref) } else { None };
                (Some(uremote.clone()), Some(ubranch), Some(uref.clone()), uexists, ucommit)
            } else {
                (None, None, None, false, None)
            };

        let is_merged = if commit.is_empty() {
            false
        } else {
            base_commits.iter().any(|bc| is_ancestor(&commit, bc))
        };

        let has_upstream = upstream_remote.is_some();
        let upstream_gone = has_upstream && !upstream_exists;

        let class = if is_base {
            if upstream_gone { LocalClass::BaseStray }
            else { LocalClass::Base }
        } else if let Some(pattern) = matches_glob(branch, protected_patterns) {
            LocalClass::Protected(pattern)
        } else if has_upstream {
            if upstream_gone {
                LocalClass::StrayTracking
            } else if is_merged {
                LocalClass::MergedTracking
            } else {
                LocalClass::Other
            }
        } else {
            if is_merged {
                LocalClass::NonTrackingMerged
            } else {
                LocalClass::Other
            }
        };

        lb_infos.push(LBranchInfo {
            name: branch.clone(),
            class,
            upstream_remote,
            upstream_branch,
            upstream_ref,
            upstream_exists,
            commit,
            upstream_commit,
        });
    }

    // Remote ref classifications
    enum RemoteClass {
        Base,
        MergedUpstream(String),      // is upstream of local branch
        MergedNonUpstream,           // not upstream of any local branch, merged
        Other,
    }

    struct RRefInfo {
        remote: String,
        branch: String,
        class: RemoteClass,
        commit: String,
        is_merged: bool,
    }

    let mut rref_infos: Vec<RRefInfo> = Vec::new();

    for remote in remotes {
        let remote_branches = get_remote_refs(remote).unwrap_or_default();
        for rbranch in remote_branches {
            let is_base = base_remote_refs.contains(&(remote.clone(), rbranch.clone()));
            let rref = format!("{}/{}", remote, rbranch);
            let commit = get_head_commit(&rref).unwrap_or_default();

            let is_merged = if commit.is_empty() {
                false
            } else {
                base_commits.iter().any(|bc| is_ancestor(&commit, bc))
            };

            let is_upstream_of = lb_infos.iter().find(|li| {
                li.upstream_remote.as_deref() == Some(remote) &&
                li.upstream_branch.as_deref() == Some(&rbranch)
            }).map(|li| li.name.clone());

            let class = if is_base {
                RemoteClass::Base
            } else if let Some(local_name) = is_upstream_of {
                if is_merged {
                    RemoteClass::MergedUpstream(local_name)
                } else {
                    RemoteClass::Other
                }
            } else {
                if is_merged {
                    RemoteClass::MergedNonUpstream
                } else {
                    RemoteClass::Other
                }
            };

            rref_infos.push(RRefInfo {
                remote: remote.clone(),
                branch: rbranch,
                class,
                commit,
                is_merged,
            });
        }
    }

    // Now figure out what to delete and what to show
    // We need to track footnotes for "some branches are skipped"

    // Footnotes
    let mut footnote_msgs: Vec<String> = Vec::new();
    let mut get_fn = |msg: &str, footnotes: &mut Vec<String>| -> u32 {
        if let Some(pos) = footnotes.iter().position(|m| m == msg) {
            (pos + 1) as u32
        } else {
            footnotes.push(msg.to_string());
            footnotes.len() as u32
        }
    };

    // Local remain/delete lists
    let mut remain_local: Vec<(String, String)> = Vec::new();  // (name, annotation)
    let mut delete_local: Vec<(String, bool)> = Vec::new();    // (name, is_non_tracking)

    // Remote remain/delete lists
    let mut remain_remote: Vec<(String, String)> = Vec::new();
    let mut delete_remote: Vec<(String, String, bool)> = Vec::new(); // (remote, branch, is_non_upstream)

    for lb in &lb_infos {
        match &lb.class {
            LocalClass::Base => {
                remain_local.push((lb.name.clone(), "base".to_string()));
            }
            LocalClass::BaseStray => {
                remain_local.push((lb.name.clone(), "stray, but: base".to_string()));
            }
            LocalClass::Protected(pattern) => {
                remain_local.push((lb.name.clone(), format!("merged, but: protected by a pattern `{}`", pattern)));
            }
            LocalClass::MergedTracking => {
                if delete_ranges.contains(&DeleteRange::MergedLocal) {
                    delete_local.push((lb.name.clone(), false));
                } else {
                    remain_local.push((lb.name.clone(), "merged, but: delete range `merged-local` was not given".to_string()));
                }
            }
            LocalClass::StrayTracking => {
                if delete_ranges.contains(&DeleteRange::Stray) {
                    delete_local.push((lb.name.clone(), false));
                } else {
                    remain_local.push((lb.name.clone(), "stray, but: delete range `stray` was not given".to_string()));
                }
            }
            LocalClass::DivergdTracking => {
                // Not implemented
                remain_local.push((lb.name.clone(), String::new()));
            }
            LocalClass::NonTrackingMerged => {
                if delete_ranges.contains(&DeleteRange::Local) {
                    delete_local.push((lb.name.clone(), true));
                } else {
                    // Footnote: Set an upstream...
                    let fn_num = {
                        let msg = "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.";
                        get_fn(msg, &mut footnote_msgs)
                    };
                    remain_local.push((lb.name.clone(), format!("*{}", fn_num)));
                }
            }
            LocalClass::Other => {
                if lb.upstream_remote.is_some() {
                    // Tracking but not merged/stray - just show as is
                    remain_local.push((lb.name.clone(), String::new()));
                } else {
                    // Non-tracking, not merged
                    let fn_num = {
                        let msg = "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.";
                        get_fn(msg, &mut footnote_msgs)
                    };
                    remain_local.push((lb.name.clone(), format!("*{}", fn_num)));
                }
            }
        }
    }

    for rr in &rref_infos {
        match &rr.class {
            RemoteClass::Base => {
                remain_remote.push((format!("{}/{}", rr.remote, rr.branch), "base".to_string()));
            }
            RemoteClass::MergedUpstream(local_name) => {
                let remote_range_matches = delete_ranges.iter().any(|r| match r {
                    DeleteRange::MergedRemote(remote) => remote == "*" || remote == &rr.remote,
                    _ => false,
                });
                if remote_range_matches {
                    // Check if the local tracking branch is in delete_local
                    delete_remote.push((rr.remote.clone(), rr.branch.clone(), false));
                } else {
                    remain_remote.push((
                        format!("{}/{}", rr.remote, rr.branch),
                        format!("merged, but: delete range `merged-remote:{}` was not given", rr.remote)
                    ));
                }
            }
            RemoteClass::MergedNonUpstream => {
                let remote_range_matches = delete_ranges.iter().any(|r| match r {
                    DeleteRange::Remote(remote) => remote == "*" || remote == &rr.remote,
                    _ => false,
                });
                if remote_range_matches {
                    delete_remote.push((rr.remote.clone(), rr.branch.clone(), true));
                } else {
                    let fn_num = {
                        let msg = "Make it upstream of a tracking branch or add `--delete 'remote:origin'` flag.";
                        get_fn(msg, &mut footnote_msgs)
                    };
                    remain_remote.push((format!("{}/{}", rr.remote, rr.branch), format!("*{}", fn_num)));
                }
            }
            RemoteClass::Other => {
                // Non-merged, non-base remote ref
                let fn_num = {
                    let msg = "Add `--delete 'merged:*'` flag.";
                    // Actually this is shown for non-upstream non-merged refs when remote:origin delete range is given
                    // But in the case where there's no relevant delete range...
                    // Actually looking at the output more carefully, it seems these are shown when 
                    // the user specified `--delete remote:origin` but the branches are not merged
                    // Let's check if we need a note
                    // For now, no note if remote range isn't in delete_ranges
                    0u32
                };
                if fn_num > 0 {
                    remain_remote.push((format!("{}/{}", rr.remote, rr.branch), format!("*{}", fn_num)));
                } else {
                    remain_remote.push((format!("{}/{}", rr.remote, rr.branch), String::new()));
                }
            }
        }
    }

    // Check if delete_remote candidates are "actually useful" -- if merged-remote:origin
    // is specified, but the local tracking branch isn't being deleted (e.g., because it's
    // not in delete_ranges for MergedLocal), we still delete the remote ref.

    // Print output
    println!();
    println!("Branches that will remain:");
    println!("  local branches:");

    for (name, annotation) in &remain_local {
        if annotation.is_empty() {
            println!("    {}", name);
        } else if annotation.starts_with('*') {
            println!("    {} {}", name, annotation);
        } else {
            println!("    {} [{}]", name, annotation);
        }
    }

    println!("  remote references:");
    for (name, annotation) in &remain_remote {
        if annotation.is_empty() {
            println!("    {}", name);
        } else if annotation.starts_with('*') {
            println!("    {} {}", name, annotation);
        } else {
            println!("    {} [{}]", name, annotation);
        }
    }

    // Footnotes
    if !footnote_msgs.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        for (i, msg) in footnote_msgs.iter().enumerate() {
            println!("    *{}: {}", i + 1, msg);
        }
    }

    println!();

    if delete_local.is_empty() && delete_remote.is_empty() {
        return Ok(());
    }

    // Group deletions by type
    let delete_merged_local: Vec<&str> = delete_local.iter()
        .filter(|(_, non_tracking)| !non_tracking)
        .map(|(n, _)| n.as_str())
        .collect();

    let delete_stray_local: Vec<&str> = lb_infos.iter()
