    /// Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]
    #[arg(long)]
    update_interval: Option<u64>,

    /// Do not ask confirm [config: trim.confirm]
    #[arg(long)]
    no_confirm: bool,

    /// Do not detach when HEAD is about to be deleted [config: trim.detach]
    #[arg(long)]
    no_detach: bool,

    /// Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]
    ///
    /// `merged` implies `merged-local,merged-remote`.
    ///
    /// `merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.
    #[arg(short, long, value_parser = parse_delete_range)]
    delete: Vec<DeleteRange>,

    /// Do not delete branches, show what branches will be deleted
    #[arg(long)]
    dry_run: bool,
}

#[derive(Debug, Clone, PartialEq)]
enum DeleteRange {
    MergedLocal,
    MergedRemote(String),  // remote name or *
    Stray,
    Diverged(String),       // remote name or *
    Local,
    Remote(String),         // remote name or *
}

fn parse_delete_range(s: &str) -> std::result::Result<DeleteRange, String> {
    match s {
        "merged-local" => Ok(DeleteRange::MergedLocal),
        "stray" => Ok(DeleteRange::Stray),
        "local" => Ok(DeleteRange::Local),
        _ => {
            if let Some(remote) = s.strip_prefix("merged-remote:") {
                Ok(DeleteRange::MergedRemote(remote.to_string()))
            } else if let Some(remote) = s.strip_prefix("diverged:") {
                Ok(DeleteRange::Diverged(remote.to_string()))
            } else if let Some(remote) = s.strip_prefix("remote:") {
                Ok(DeleteRange::Remote(remote.to_string()))
            } else if let Some(remote) = s.strip_prefix("merged:") {
                // merged:<remote> expands to merged-local,merged-remote:<remote>
                // But we can't return two values here. We'll handle this specially.
                // Return a special marker
                Ok(DeleteRange::MergedRemote(format!("__merged__{}", remote)))
            } else {
                Err(format!("Invalid delete range format `{}`", s))
            }
        }
    }
}

fn git(args: &[&str]) -> Result<String> {
    let output = Command::new("git")
        .args(args)
        .output()
        .context("Failed to run git")?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn git_config(key: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["config", "--get", key])
        .output()
        .ok()?;
    if output.status.success() {
        Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        None
    }
}

fn git_ok(args: &[&str]) -> bool {
    Command::new("git")
        .args(args)
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn git_output_lines(args: &[&str]) -> Result<Vec<String>> {
    let output = Command::new("git")
        .args(args)
        .output()
        .context("Failed to run git")?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout);
        Ok(s.lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn git_output_lines_raw(args: &[&str]) -> Result<Vec<String>> {
    let output = Command::new("git")
        .args(args)
        .output()
        .context("Failed to run git")?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout);
        Ok(s.lines().map(|l| l.to_string()).collect())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn is_ancestor(commit: &str, base: &str) -> bool {
    Command::new("git")
        .args(["merge-base", "--is-ancestor", commit, base])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn get_remotes() -> Result<Vec<String>> {
    git_output_lines(&["remote"])
}

fn get_local_branches() -> Result<Vec<String>> {
    let lines = git_output_lines_raw(&["branch", "--format=%(refname:short)"])?;
    Ok(lines.into_iter().filter(|l| !l.is_empty()).collect())
}

/// Returns (upstream, remote, merge) for a branch
fn get_branch_upstream(branch: &str) -> Option<(String, String, String)> {
    // Get upstream ref
    let upstream = Command::new("git")
        .args(["rev-parse", "--abbrev-ref", &format!("{}@{{upstream}}", branch)])
        .output()
        .ok()?;
    if !upstream.status.success() {
        return None;
    }
    let upstream_ref = String::from_utf8_lossy(&upstream.stdout).trim().to_string();

    // Parse remote/branch from upstream ref like "origin/feature1"
    let remote = Command::new("git")
        .args(["config", &format!("branch.{}.remote", branch)])
        .output()
        .ok()?;
    if !remote.status.success() {
        return None;
    }
    let remote_name = String::from_utf8_lossy(&remote.stdout).trim().to_string();

    let merge = Command::new("git")
        .args(["config", &format!("branch.{}.merge", branch)])
        .output()
        .ok()?;
    if !merge.status.success() {
        return None;
    }
    let merge_ref = String::from_utf8_lossy(&merge.stdout).trim().to_string();

    Some((upstream_ref, remote_name, merge_ref))
}

/// Get all remote tracking refs
fn get_remote_refs(remote: &str) -> Result<Vec<String>> {
    let lines = git_output_lines_raw(&["branch", "-r", "--format=%(refname:short)"])?;
    let prefix = format!("{}/", remote);
    Ok(lines.into_iter()
        .filter(|l| !l.is_empty() && l.starts_with(&prefix) && !l.contains("->"))
        .map(|l| l[prefix.len()..].to_string())
        .collect())
}

fn get_head_commit(branch: &str) -> Option<String> {
    Command::new("git")
        .args(["rev-parse", branch])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
}

fn get_current_branch() -> Option<String> {
    let output = Command::new("git")
        .args(["symbolic-ref", "--short", "HEAD"])
        .output()
        .ok()?;
    if output.status.success() {
        Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        None
    }
}

fn find_remote_head_branch(remote: &str) -> Option<String> {
    // Try git symbolic-ref refs/remotes/{remote}/HEAD
    let output = Command::new("git")
        .args(["symbolic-ref", &format!("refs/remotes/{}/HEAD", remote)])
        .output()
        .ok()?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout).trim().to_string();
        // s is like "refs/remotes/origin/master"
        let prefix = format!("refs/remotes/{}/", remote);
        if s.starts_with(&prefix) {
            return Some(s[prefix.len()..].to_string());
        }
    }
    None
}

/// Check if a local branch exists 
fn local_branch_exists(name: &str) -> bool {
    Command::new("git")
        .args(["rev-parse", "--verify", &format!("refs/heads/{}", name)])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// Check if a remote tracking ref exists
fn remote_ref_exists(remote: &str, branch: &str) -> bool {
    Command::new("git")
        .args(["rev-parse", "--verify", &format!("refs/remotes/{}/{}", remote, branch)])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn delete_remote_branch(remote: &str, branch: &str, dry_run: bool) -> Result<()> {
    let refspec = format!("refs/heads/{}", branch);
    if dry_run {
        // Still simulate the push output
        println!("To {}", get_remote_url(remote).unwrap_or_default());
        println!(" - [deleted]         {}", branch);
    } else {
        let output = Command::new("git")
            .args(["push", remote, "--delete", &refspec])
            .output()
            .context("Failed to run git push")?;
        // Print stderr (which has the push output)
        let stderr = String::from_utf8_lossy(&output.stderr);
        print!("{}", stderr);
        if !output.status.success() {
            return Err(anyhow!("Failed to delete remote branch {}/{}", remote, branch));
        }
    }
    Ok(())
}

fn get_remote_url(remote: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["remote", "get-url", remote])
        .output()
        .ok()?;
    if output.status.success() {
        Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        None
    }
}

fn delete_local_branch(branch: &str, dry_run: bool, current: &Option<String>) -> Result<()> {
    if dry_run {
        println!("Delete branch {} (dry run).", branch);
    } else {
        let output = Command::new("git")
            .args(["branch", "-D", branch])
            .output()
            .context("Failed to run git branch -D")?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        print!("{}", stdout);
        if !output.status.success() {
            return Err(anyhow!("Failed to delete local branch {}", branch));
        }
    }
    Ok(())
}

fn detach_head(commit: &str, dry_run: bool) -> Result<()> {
    if dry_run {
        println!("Note: switching to '{}' (dry run)", commit);
        println!("You are in 'detached HED' state... blah blah...");
        println!("HEAD is now at {} {}", &commit[..7.min(commit.len())], get_commit_message(commit).unwrap_or_default());
    } else {
        let output = Command::new("git")
            .args(["checkout", "--detach", commit])
            .output()
            .context("Failed to detach HEAD")?;
        let stderr = String::from_utf8_lossy(&output.stderr);
        eprint!("{}", stderr);
        if !output.status.success() {
            return Err(anyhow!("Failed to detach HEAD"));
        }
    }
    Ok(())
}

fn get_commit_message(commit: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["log", "--format=%s", "-1", commit])
        .output()
        .ok()?;
    if output.status.success() {
        Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        None
    }
}

fn matches_glob(name: &str, patterns: &[String]) -> Option<String> {
    for p in patterns {
        if let Ok(pat) = Pattern::new(p) {
            if pat.matches(name) {
                return Some(p.clone());
            }
        }
    }
    None
}

fn fetch_remote(remote: &str) {
    let output = Command::new("git")
        .args(["fetch", "--prune", remote])
        .output();
    match output {
        Ok(o) => {
            let stderr = String::from_utf8_lossy(&o.stderr);
            // Print fetch output like "Fetching origin"
            // the actual fetching happens silently, but let's print the fetch messages
            if !stderr.is_empty() {
                eprint!("{}", stderr);
            }
        }
        Err(_) => {}
    }
    // Print "Fetching <remote>" like git trim does
    println!("Fetching {}", remote);
}

fn get_fetch_timestamp_path(remote: &str) -> Option<std::path::PathBuf> {
    let git_dir = Command::new("git")
        .args(["rev-parse", "--git-dir"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())?;
    let path = std::path::PathBuf::from(&git_dir)
        .join("FETCH_HEAD");
    // Actually check git fetch log or FETCH_HEAD timestamp
    // Git stores fetch timestamp in FETCH_HEAD file modification time
    Some(std::path::PathBuf::from(&git_dir).join("FETCH_HEAD"))
}

fn seconds_since_last_fetch() -> Option<u64> {
    let git_dir = Command::new("git")
        .args(["rev-parse", "--git-dir"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())?;
    let fetch_head = std::path::PathBuf::from(&git_dir).join("FETCH_HEAD");
    let metadata = std::fs::metadata(&fetch_head).ok()?;
    let modified = metadata.modified().ok()?;
    let now = SystemTime::now();
    let elapsed = now.duration_since(modified).ok()?;
    Some(elapsed.as_secs())
}

fn normalize_delete_ranges(ranges: Vec<DeleteRange>) -> Vec<DeleteRange> {
    let mut result = Vec::new();
    for r in ranges {
        match r {
            DeleteRange::MergedRemote(ref s) if s.starts_with("__merged__") => {
                let remote = s[10..].to_string();
                result.push(DeleteRange::MergedLocal);
                result.push(DeleteRange::MergedRemote(remote));
            }
            _ => result.push(r),
        }
    }
    result
}

#[derive(Debug)]
enum BranchStatus {
    Base,
    MergedLocal,        // tracking branch, upstream exists, merged
    MergedRemote,       // remote ref, merged into base
    Stray,              // tracking branch, upstream gone
    DiverggedLocal,     // tracking branch, merged partially (upstream diverged)
    DiverggedRemote,    // remote ref, diverged (was merged at some point)
    NonTrackingLocal,   // local branch with no upstream
    NonTrackingRemote,  // remote ref that is not upstream of any local
}

fn main() -> Result<()> {
    let args = Args::parse();

    // Expand delete ranges  
    let mut delete_ranges = normalize_delete_ranges(args.delete.clone());

    // Read from git config if not specified
    let bases_opt = args.bases.clone().or_else(|| git_config("trim.bases"));
    let protected_opt = args.protected.clone().or_else(|| git_config("trim.protected"));
    let no_update = args.no_update || git_config("trim.update").map(|v| v == "false").unwrap_or(false);
    let no_confirm = args.no_confirm || git_config("trim.confirm").map(|v| v == "false").unwrap_or(false);
    let no_detach = args.no_detach || git_config("trim.detach").map(|v| v == "false").unwrap_or(false);
    let update_interval = args.update_interval
        .or_else(|| git_config("trim.updateInterval").and_then(|v| v.parse().ok()))
        .unwrap_or(5);

    // Default delete range
    if delete_ranges.is_empty() {
        delete_ranges = vec![DeleteRange::MergedLocal, DeleteRange::MergedRemote("origin".to_string())];
    }

    // Check we're in a git repo
    if !git_ok(&["rev-parse", "--git-dir"]) {
        return Err(anyhow!("Not a git repository"));
    }

    // Get remotes
    let remotes = get_remotes()?;
    if remotes.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }

    // Update remotes if needed
    if !no_update && !args.dry_run {
        let should_fetch = if update_interval == 0 {
            true
        } else {
            match seconds_since_last_fetch() {
                Some(secs) => secs >= update_interval,
                None => true,
            }
        };
        if should_fetch {
            for remote in &remotes {
                fetch_remote(remote);
            }
        }
    } else if !no_update && args.dry_run {
        // In dry-run, still fetch 
        let should_fetch = if update_interval == 0 {
            true
        } else {
            match seconds_since_last_fetch() {
                Some(secs) => secs >= update_interval,
                None => true,
            }
        };
        if should_fetch {
            for remote in &remotes {
                fetch_remote(remote);
            }
        }
    }

    // Determine base branches
    let base_branches: Vec<String> = if let Some(bases_str) = &bases_opt {
        bases_str.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
    } else {
        // Find branches that track symbolic refs
        let mut bases = Vec::new();
        for remote in &remotes {
            if let Some(head_branch) = find_remote_head_branch(remote) {
                // Find local branch tracking this
                let local_branches = get_local_branches().unwrap_or_default();
                for lb in &local_branches {
                    if let Some((_, r, m)) = get_branch_upstream(lb) {
                        if r == *remote {
                            // Check if merge ref matches
                            let merge_branch = m.strip_prefix("refs/heads/").unwrap_or(&m);
                            if merge_branch == head_branch {
                                bases.push(lb.clone());
                                break;
                            }
                        }
                    }
                }
                // If no local branch found tracking this HEAD, still consider it as a base target
                if bases.is_empty() {
                    // No local branch tracks remote HEAD
                }
            }
        }
        bases
    };

    if base_branches.is_empty() {
        eprintln!("I can't detect base branch! Try following any resolution:");
        eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
        eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
        eprintln!("   to set an upstream branch for <base branch> if exists.");
        eprintln!("You also can set bases manually with any of following commands:");
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
        return Err(anyhow!("No base branch is found!"));
    }

    // Protected patterns
    let protected_patterns: Vec<String> = if let Some(p) = &protected_opt {
        p.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
    } else {
        Vec::new()
    };

    // Collect all base commits (merge base refs)
    // Base commits are the HEAD commits of base branches' upstreams
    let mut base_commits: HashSet<String> = HashSet::new();
    let mut base_remote_refs: HashSet<(String, String)> = HashSet::new(); // (remote, branch)

    for base in &base_branches {
        // Get the upstream of the base branch
        if let Some((upstream, remote, _)) = get_branch_upstream(base) {
            // upstream is like "origin/master"
            let branch_part = upstream.strip_prefix(&format!("{}/", remote)).unwrap_or(&upstream);
            base_remote_refs.insert((remote.clone(), branch_part.to_string()));
            if let Some(commit) = get_head_commit(&upstream) {
                base_commits.insert(commit);
            }
            // Also get the local base commit
            if let Some(commit) = get_head_commit(base) {
                base_commits.insert(commit);
            }
        } else {
            // Base branch with no upstream (direct merge base)
            if let Some(commit) = get_head_commit(base) {
                base_commits.insert(commit);
            }
        }
    }

    // Determine which delete ranges require scanning remote refs
    let needs_remote_scan: HashSet<String> = delete_ranges.iter().filter_map(|r| {
        match r {
            DeleteRange::MergedRemote(remote) => Some(remote.clone()),
            DeleteRange::Diverged(remote) => Some(remote.clone()),
            DeleteRange::Remote(remote) => Some(remote.clone()),
            _ => None,
        }
    }).collect();

    // Check if we're scanning all or specific remotes
    let scan_all_remotes = needs_remote_scan.contains("*");

    // Get all local branches
    let local_branches = get_local_branches()?;

    // Current branch
    let current_branch = get_current_branch();

    // Build the data model
    // For each local branch, determine its status
    struct LocalBranchInfo {
        name: String,
        upstream_remote: Option<String>,  // e.g., "origin"
        upstream_branch: Option<String>,  // e.g., "feature1"
        upstream_ref: Option<String>,     // e.g., "origin/feature1"
        upstream_exists: bool,
        is_base: bool,
        is_merged_into_base: bool,         // local head is ancestor of any base
        upstream_is_merged_into_base: bool, // upstream ref is ancestor of any base
        upstream_ahead: bool,               // upstream has commits not in any base
        commit: String,
        upstream_commit: Option<String>,
    }

    let mut local_info: Vec<LocalBranchInfo> = Vec::new();

    for branch in &local_branches {
        let is_base = base_branches.contains(branch);
        let commit = get_head_commit(branch).unwrap_or_default();

        let upstream_info = get_branch_upstream(branch);
        let (upstream_remote, upstream_branch, upstream_ref, upstream_exists, upstream_commit) = 
            if let Some((uref, uremote, umerge)) = &upstream_info {
                let ubranch = umerge.strip_prefix("refs/heads/").unwrap_or(umerge).to_string();
                let uexists = remote_ref_exists(uremote, &ubranch);
                let ucommit = if uexists { get_head_commit(uref) } else { None };
                (Some(uremote.clone()), Some(ubranch), Some(uref.clone()), uexists, ucommit)
            } else {
                (None, None, None, false, None)
            };

        // Is local branch merged into base?
        let is_merged_into_base = if commit.is_empty() {
            false
        } else {
            base_commits.iter().any(|bc| is_ancestor(&commit, bc))
        };

        // Is upstream merged into base?
        let upstream_is_merged_into_base = if let Some(ref uc) = upstream_commit {
            base_commits.iter().any(|bc| is_ancestor(uc, bc))
        } else {
            false
        };

        // Is upstream ahead of what was merged? 
        // (i.e., the upstream has extra commits not in base, but some earlier version was merged)
        let upstream_ahead = if let Some(ref uc) = upstream_commit {
            // upstream exists but NOT all commits are in base
            !base_commits.iter().any(|bc| is_ancestor(uc, bc))
        } else {
            false
        };

        local_info.push(LocalBranchInfo {
            name: branch.clone(),
            upstream_remote,
            upstream_branch,
            upstream_ref,
            upstream_exists,
            is_base,
            is_merged_into_base,
            upstream_is_merged_into_base,
            upstream_ahead,
            commit,
            upstream_commit,
        });
    }

    // Build remote ref info
    struct RemoteRefInfo {
        remote: String,
        branch: String,
        is_base: bool,
        is_merged_into_base: bool,
        is_upstream_of: Option<String>,  // local branch name that uses this as upstream
    }

    let mut remote_info: Vec<RemoteRefInfo> = Vec::new();

    // Collect all remote refs
    for remote in &remotes {
        let remote_branches = get_remote_refs(remote).unwrap_or_default();
        for rbranch in remote_branches {
            let is_base = base_remote_refs.contains(&(remote.clone(), rbranch.clone()));
            let rref = format!("{}/{}", remote, rbranch);
            let commit = get_head_commit(&rref).unwrap_or_default();

            let is_merged = if commit.is_empty() {
                false
            } else {
                base_commits.iter().any(|bc| is_ancestor(&commit, bc))
            };

            // Find if this is upstream of any local branch
            let is_upstream_of = local_info.iter().find(|li| {
                li.upstream_remote.as_deref() == Some(remote) &&
                li.upstream_branch.as_deref() == Some(&rbranch)
            }).map(|li| li.name.clone());

            remote_info.push(RemoteRefInfo {
                remote: remote.clone(),
                branch: rbranch,
                is_base,
                is_merged_into_base: is_merged,
                is_upstream_of,
            });
        }
    }

