                DeleteRange::MergedRemote(remote) => remote == "*" || remote == &info.remote,
                _ => false,
            });

            if is_upstream {
                // This is an upstream of a local branch
                if remote_range_matches {
                    // Check if the local tracking branch is also being deleted or not
                    delete_remote.push((info.remote.clone(), info.branch.clone(), false));
                } else {
                    remain_remote.push((format!("{}/{}", info.remote, info.branch), format!("merged, but: delete range `merged-remote:{}` was not given", info.remote)));
                }
            } else {
                // Non-upstream merged remote ref
                let remote_range = delete_ranges.iter().any(|r| match r {
                    DeleteRange::Remote(remote) => remote == "*" || remote == &info.remote,
                    _ => false,
                });
                if remote_range {
                    delete_remote.push((info.remote.clone(), info.branch.clone(), true));
                } else {
                    // Skipped with footnote *3
                    remain_remote.push((format!("{}/{}", info.remote, info.branch), String::new()));
                }
            }
        } else {
            // Not merged
            if !is_upstream {
                // Non-upstream not-merged remote ref
