    let mut all_remote_deletes: Vec<(String, String, bool)> = Vec::new(); // (remote, branch, is_non_upstream)

    for (remote, branches) in &delete_remote_upstream {
        let mut sorted_branches = branches.clone();
        sorted_branches.sort();
