    all_remote_deletes.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));

    if !all_remote_deletes.is_empty() {
        println!("Delete merged remote refs:");
        for (remote, branch, non_upstream) in &all_remote_deletes {
            if *non_upstream {
                println!("  - {}, refs/heads/{} (non-upstream)", remote, branch);
            } else {
                println!("  - {}, refs/heads/{}", remote, branch);
            }
        }
    }

    if !delete_stray.is_empty() {
        println!("Delete stray local branches:");
        for name in &delete_stray {
            println!("  - {}", name);
        }
    }

    // Confirm if needed
    if !args.dry_run && !no_confirm {
        // Check if stdin/stdout is a terminal
        if !io::stdin().is_terminal() {
            return Err(anyhow!("IO error: not a terminal\n\nCaused by:\n    not a terminal"));
        }

        // Ask confirmation
        let confirmed = dialoguer::Confirm::new()
            .with_prompt("Confirm?")
            .default(false)
            .interact()?;

        if !confirmed {
            println!("Cancelled");
            return Ok(());
        }
    }

    // Execute deletions
    // 1. Remote deletes (all via push --delete)
    // Group by remote
    let mut remote_branches_to_delete: HashMap<String, Vec<String>> = HashMap::new();
    for (remote, branch, _) in &all_remote_deletes {
        remote_branches_to_delete.entry(remote.clone()).or_default().push(branch.clone());
    }

    for (remote, branches) in &remote_branches_to_delete {
        let mut sorted = branches.clone();
        sorted.sort();
        push_delete_remote_branches(remote, &sorted, args.dry_run);
    }

    // 2. Local deletes
    // Order: check if current branch needs detach first
    // Collect all local branches to delete
    let mut all_local_to_delete: Vec<(String, &str)> = Vec::new(); // (name, type: stray/merged/non-tracking)

    for name in &delete_stray {
