    #[arg(long)]
    no_detach: bool,

    /// Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]
    ///
    /// `merged` implies `merged-local,merged-remote`.
    ///
    /// `merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.
    #[arg(short, long, value_parser = parse_delete_spec, value_delimiter = ',')]
    delete: Vec<DeleteSpec>,

    /// Do not delete branches, show what branches will be deleted
    #[arg(long)]
    dry_run: bool,
}

#[derive(Debug, Clone, PartialEq)]
enum DeleteSpec {
    MergedLocal,
    MergedRemote(String),  // remote name or *
    Stray,
    Diverged(String),      // remote name or *
    Local,
    Remote(String),        // remote name or *
}

fn parse_delete_spec(s: &str) -> std::result::Result<DeleteSpec, String> {
    match s.trim() {
        "merged-local" => Ok(DeleteSpec::MergedLocal),
        "stray" => Ok(DeleteSpec::Stray),
        "local" => Ok(DeleteSpec::Local),
        other => {
            if let Some(remote) = other.strip_prefix("merged-remote:") {
                Ok(DeleteSpec::MergedRemote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("diverged:") {
                Ok(DeleteSpec::Diverged(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("remote:") {
                Ok(DeleteSpec::Remote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("merged:") {
                // merged:<remote> is a shorthand for merged-local + merged-remote:<remote>
                // We encode this as a special value; we'll expand it later
                Ok(DeleteSpec::MergedRemote(format!("\x00merged\x00{}", remote)))
            } else {
                Err(format!("Invalid delete range format `{}`", other))
            }
        }
    }
}

fn expand_delete_specs(specs: Vec<DeleteSpec>) -> Vec<DeleteSpec> {
    let mut result = Vec::new();
    for spec in specs {
        match spec {
            DeleteSpec::MergedRemote(ref s) if s.starts_with('\x00') => {
                let remote = s["\x00merged\x00".len()..].to_string();
                result.push(DeleteSpec::MergedLocal);
                result.push(DeleteSpec::MergedRemote(remote));
            }
            _ => result.push(spec),
        }
    }
    result
}

fn git_run(args: &[&str]) -> Result<String> {
    let output = Command::new("git")
        .args(args)
        .output()
        .with_context(|| format!("Failed to run git {}", args.join(" ")))?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

