use anyhow::{anyhow, Context, Result};
use clap::Parser;
use glob::Pattern;
use std::collections::{HashMap, HashSet};
use std::io::{self, IsTerminal};
use std::process::Command;
use std::time::SystemTime;

const VERSION: &str = "0.4.4";

#[derive(Parser, Debug)]
#[command(
    name = "git-trim",
    version = VERSION,
    about = "Automatically trims your tracking branches whose upstream branches are merged or stray.\n`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`."
)]
struct Args {
    /// Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]
    ///
    /// The default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.
    #[arg(short, long)]
    bases: Option<String>,

    /// Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]
    #[arg(short, long)]
    protected: Option<String>,

    /// Do not update remotes [config: trim.update]
    #[arg(long)]
    no_update: bool,

    /// Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]
    #[arg(long)]
    update_interval: Option<u64>,

    /// Do not ask confirm [config: trim.confirm]
    #[arg(long)]
    no_confirm: bool,

    /// Do not detach when HEAD is about to be deleted [config: trim.detach]
    #[arg(long)]
    no_detach: bool,

    /// Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]
    ///
    /// `merged` implies `merged-local,merged-remote`.
    ///
    /// `merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.
    #[arg(short, long, value_parser = parse_delete_spec, value_delimiter = ',')]
    delete: Vec<DeleteSpec>,

    /// Do not delete branches, show what branches will be deleted
    #[arg(long)]
    dry_run: bool,
}

#[derive(Debug, Clone, PartialEq)]
enum DeleteSpec {
    MergedLocal,
    MergedRemote(String),  // remote name or *
    Stray,
    Diverged(String),      // remote name or *
    Local,
    Remote(String),        // remote name or *
}

fn parse_delete_spec(s: &str) -> std::result::Result<DeleteSpec, String> {
    match s.trim() {
        "merged-local" => Ok(DeleteSpec::MergedLocal),
        "stray" => Ok(DeleteSpec::Stray),
        "local" => Ok(DeleteSpec::Local),
        other => {
            if let Some(remote) = other.strip_prefix("merged-remote:") {
                Ok(DeleteSpec::MergedRemote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("diverged:") {
                Ok(DeleteSpec::Diverged(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("remote:") {
                Ok(DeleteSpec::Remote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("merged:") {
                // merged:<remote> is a shorthand for merged-local + merged-remote:<remote>
                // We encode this as a special value; we'll expand it later
                Ok(DeleteSpec::MergedRemote(format!("\x00merged\x00{}", remote)))
            } else {
                Err(format!("Invalid delete range format `{}`", other))
            }
        }
    }
}

fn expand_delete_specs(specs: Vec<DeleteSpec>) -> Vec<DeleteSpec> {
    let mut result = Vec::new();
    for spec in specs {
        match spec {
            DeleteSpec::MergedRemote(ref s) if s.starts_with('\x00') => {
                let remote = s["\x00merged\x00".len()..].to_string();
                result.push(DeleteSpec::MergedLocal);
                result.push(DeleteSpec::MergedRemote(remote));
            }
            _ => result.push(spec),
        }
    }
    result
}

fn git_run(args: &[&str]) -> Result<String> {
    let output = Command::new("git")
        .args(args)
        .output()
        .with_context(|| format!("Failed to run git {}", args.join(" ")))?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn git_config_get(key: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["config", "--get", key])
        .output()
        .ok()?;
    if output.status.success() {
        Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        None
    }
}

fn git_ok(args: &[&str]) -> bool {
    Command::new("git")
        .args(args)
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn git_lines(args: &[&str]) -> Result<Vec<String>> {
    let output = Command::new("git")
        .args(args)
        .output()
        .with_context(|| format!("Failed to run git {}", args.join(" ")))?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout);
        Ok(s.lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect())
    } else {
        Err(anyhow!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn is_ancestor(commit: &str, of: &str) -> bool {
    Command::new("git")
        .args(["merge-base", "--is-ancestor", commit, of])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn get_remote_url(remote: &str) -> String {
    Command::new("git")
        .args(["remote", "get-url", remote])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .unwrap_or_default()
}

fn get_head_commit(refname: &str) -> Option<String> {
    Command::new("git")
        .args(["rev-parse", refname])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
}

fn get_short_commit(refname: &str) -> Option<String> {
    Command::new("git")
        .args(["rev-parse", "--short", refname])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
}

fn get_commit_subject(commit: &str) -> Option<String> {
    Command::new("git")
        .args(["log", "--format=%s", "-1", commit])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
}

fn get_remotes() -> Result<Vec<String>> {
    git_lines(&["remote"])
}

fn get_local_branches() -> Result<Vec<String>> {
    let output = Command::new("git")
        .args(["branch", "--format=%(refname:short)"])
        .output()
        .context("Failed to run git branch")?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout);
        Ok(s.lines()
            .map(|l| l.to_string())
            .filter(|l| !l.is_empty())
            .collect())
    } else {
        Err(anyhow!("git branch failed"))
    }
}

fn get_branch_remote(branch: &str) -> Option<String> {
    Command::new("git")
        .args(["config", &format!("branch.{}.remote", branch)])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
}

fn get_branch_merge(branch: &str) -> Option<String> {
    Command::new("git")
        .args(["config", &format!("branch.{}.merge", branch)])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
}

/// Returns (remote_name, remote_branch) for a branch's upstream
fn get_branch_upstream(branch: &str) -> Option<(String, String)> {
    let remote = get_branch_remote(branch)?;
    let merge = get_branch_merge(branch)?;
    let branch_name = merge.strip_prefix("refs/heads/")
        .unwrap_or(&merge)
        .to_string();
    Some((remote, branch_name))
}

fn remote_ref_exists(remote: &str, branch: &str) -> bool {
    Command::new("git")
        .args(["rev-parse", "--verify", &format!("refs/remotes/{}/{}", remote, branch)])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn get_remote_branches(remote: &str) -> Vec<String> {
    let output = Command::new("git")
        .args(["branch", "-r", "--format=%(refname:short)"])
        .output()
        .ok()
        .filter(|o| o.status.success());

    match output {
        Some(o) => {
            let s = String::from_utf8_lossy(&o.stdout);
            let prefix = format!("{}/", remote);
            s.lines()
                .map(|l| l.trim().to_string())
                .filter(|l| !l.is_empty() && l.starts_with(&prefix) && !l.contains("->"))
                .map(|l| l[prefix.len()..].to_string())
                .collect()
        }
        None => Vec::new(),
    }
}

fn get_current_branch() -> Option<String> {
    Command::new("git")
        .args(["symbolic-ref", "--short", "HEAD"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
}

fn find_remote_head_branch(remote: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["symbolic-ref", &format!("refs/remotes/{}/HEAD", remote)])
        .output()
        .ok()
        .filter(|o| o.status.success())?;
    let s = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let prefix = format!("refs/remotes/{}/", remote);
    if s.starts_with(&prefix) {
        Some(s[prefix.len()..].to_string())
    } else {
        None
    }
}

fn glob_matches(name: &str, patterns: &[String]) -> Option<String> {
    for p in patterns {
        if let Ok(pat) = Pattern::new(p) {
            if pat.matches(name) {
                return Some(p.clone());
            }
        }
    }
    None
}

fn seconds_since_last_fetch() -> Option<u64> {
    let git_dir = Command::new("git")
        .args(["rev-parse", "--git-dir"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())?;
    let fetch_head = std::path::PathBuf::from(&git_dir).join("FETCH_HEAD");
    let metadata = std::fs::metadata(&fetch_head).ok()?;
    let modified = metadata.modified().ok()?;
    let now = SystemTime::now();
    let elapsed = now.duration_since(modified).ok()?;
    Some(elapsed.as_secs())
}

fn do_fetch(remotes: &[String]) {
    for remote in remotes {
        println!("Fetching {}", remote);
        let output = Command::new("git")
            .args(["fetch", "--prune", remote])
            .output();
        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr);
                if !stderr.is_empty() {
                    eprint!("{}", stderr);
                }
            }
            Err(e) => {
                eprintln!("Failed to fetch {}: {}", remote, e);
            }
        }
    }
}

fn push_delete_remote_branches(remote: &str, branches: &[String], dry_run: bool) {
    let mut args = vec!["push", remote];
    if dry_run {
        args.push("--dry-run");
    }
    args.push("--delete");
    let refspecs: Vec<String> = branches.iter().map(|b| format!("refs/heads/{}", b)).collect();
    for r in &refspecs {
        args.push(r.as_str());
    }
    let output = Command::new("git")
        .args(&args)
        .output();
    match output {
        Ok(o) => {
            let stderr = String::from_utf8_lossy(&o.stderr);
            print!("{}", stderr);
        }
        Err(e) => {
            eprintln!("Failed to push delete: {}", e);
        }
    }
}

fn delete_local_branch(branch: &str) -> String {
    let output = Command::new("git")
        .args(["branch", "-D", branch])
        .output();
    match output {
        Ok(o) => String::from_utf8_lossy(&o.stdout).trim().to_string(),
        Err(e) => format!("Error: {}", e),
    }
}

fn detach_head_actual(commit_ref: &str) {
    println!("Note: switching to '{}'.", commit_ref);
    let output = Command::new("git")
        .args(["checkout", "--detach", commit_ref])
        .output();
    match output {
        Ok(o) => {
            let stderr = String::from_utf8_lossy(&o.stderr);
            print!("{}", stderr);
        }
        Err(e) => {
            eprintln!("Failed to detach HEAD: {}", e);
        }
    }
}

fn detach_head_dry_run(commit_ref: &str) {
    let short = get_short_commit(commit_ref).unwrap_or_default();
    let subject = commit_ref.strip_prefix("refs/heads/")
        .and_then(|branch| get_commit_subject(branch))
        .unwrap_or_default();
    println!("Note: switching to '{}' (dry run)", commit_ref);
    println!("You are in 'detached HED' state... blah blah...");
    println!("HEAD is now at {} {} (dry run)", short, subject);
}

fn main() -> Result<()> {
    let args = Args::parse();

    // Expand and collect delete specs
    let raw_specs = if args.delete.is_empty() {
        // Default: merged:origin = merged-local + merged-remote:origin
        vec![DeleteSpec::MergedLocal, DeleteSpec::MergedRemote("origin".to_string())]
    } else {
        expand_delete_specs(args.delete.clone())
    };

    // Read git config overrides
    let no_update = args.no_update 
        || git_config_get("trim.update").map(|v| v == "false").unwrap_or(false);
    let no_confirm = args.no_confirm 
        || git_config_get("trim.confirm").map(|v| v == "false").unwrap_or(false);
    let no_detach = args.no_detach 
        || git_config_get("trim.detach").map(|v| v == "false").unwrap_or(false);
    let update_interval: u64 = args.update_interval
        .or_else(|| git_config_get("trim.updateInterval").and_then(|v| v.parse().ok()))
        .unwrap_or(5);

    // Check git repo
    if !git_ok(&["rev-parse", "--git-dir"]) {
        return Err(anyhow!("Not a git repository"));
    }

    // Get remotes
    let remotes = get_remotes()?;
    if remotes.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }

    // Fetch if needed
    if !no_update {
        let should_fetch = if update_interval == 0 {
            true
        } else {
            match seconds_since_last_fetch() {
                Some(secs) => secs >= update_interval,
                None => true,
            }
        };
        if should_fetch {
            do_fetch(&remotes);
        }
    }

    // Determine base branches
    let bases_from_config = args.bases.clone()
        .or_else(|| git_config_get("trim.bases"));

    let base_branches: Vec<String> = if let Some(s) = bases_from_config {
        s.split(',')
            .map(|b| b.trim().to_string())
            .filter(|b| !b.is_empty())
            .collect()
    } else {
        // Auto-detect: find local branches tracking remote HEAD
        let local_branches = get_local_branches()?;
        let mut bases = Vec::new();
        for remote in &remotes {
            if let Some(head_branch) = find_remote_head_branch(remote) {
                for lb in &local_branches {
                    if let Some((r, m)) = get_branch_upstream(lb) {
                        if r == *remote && m == head_branch {
                            bases.push(lb.clone());
                            break;
                        }
                    }
                }
            }
        }
        bases
    };

    if base_branches.is_empty() {
        eprintln!("I can't detect base branch! Try following any resolution:");
        eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
        eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
        eprintln!("   to set an upstream branch for <base branch> if exists.");
        eprintln!("You also can set bases manually with any of following commands:");
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
        return Err(anyhow!("No base branch is found!"));
    }

    // Protected patterns
    let protected: Vec<String> = args.protected.clone()
        .or_else(|| git_config_get("trim.protected"))
        .map(|s| s.split(',').map(|p| p.trim().to_string()).filter(|p| !p.is_empty()).collect())
        .unwrap_or_default();

    // Compute base commits and base remote refs
    let mut base_commits: HashSet<String> = HashSet::new();
    let mut base_remote_refs: HashSet<(String, String)> = HashSet::new();

    for base in &base_branches {
        // Get local base commit
        if let Some(commit) = get_head_commit(&format!("refs/heads/{}", base)) {
            base_commits.insert(commit);
        }
        // Get upstream base commit
        if let Some((remote, branch)) = get_branch_upstream(base) {
            let rref = format!("refs/remotes/{}/{}", remote, branch);
            if let Some(commit) = get_head_commit(&rref) {
                base_commits.insert(commit);
            }
            base_remote_refs.insert((remote, branch));
        }
    }

    // Get current branch
    let current_branch = get_current_branch();

    // Get all local branches
    let local_branches = get_local_branches()?;

    // Process local branches
    #[derive(Debug)]
    struct LocalBranchEntry {
        name: String,
        upstream_remote: Option<String>,
        upstream_branch: Option<String>,
        upstream_exists: bool,
        is_base: bool,
        is_merged: bool,
        is_current: bool,
    }

    let mut lb_entries: Vec<LocalBranchEntry> = Vec::new();

    for branch in &local_branches {
        let is_base = base_branches.contains(branch);
        let is_current = current_branch.as_deref() == Some(branch.as_str());

        let upstream = get_branch_upstream(branch);
        let (upstream_remote, upstream_branch, upstream_exists) = match &upstream {
            Some((remote, branch_name)) => {
                let exists = remote_ref_exists(remote, branch_name);
                (Some(remote.clone()), Some(branch_name.clone()), exists)
            }
            None => (None, None, false),
        };

        // Check if local branch is merged into any base
        let commit = get_head_commit(&format!("refs/heads/{}", branch));
        let is_merged = match &commit {
            Some(c) => base_commits.iter().any(|bc| is_ancestor(c, bc)),
            None => false,
        };

        lb_entries.push(LocalBranchEntry {
            name: branch.clone(),
            upstream_remote,
            upstream_branch,
            upstream_exists,
            is_base,
            is_merged,
            is_current,
        });
    }

    // Process remote refs
    #[derive(Debug)]
    struct RemoteRefEntry {
        remote: String,
        branch: String,
        is_base: bool,
        is_merged: bool,
        upstream_of: Option<String>, // local branch name
    }

    let mut rr_entries: Vec<RemoteRefEntry> = Vec::new();

    for remote in &remotes {
        let remote_branches = get_remote_branches(remote);
        for branch in remote_branches {
            let is_base = base_remote_refs.contains(&(remote.clone(), branch.clone()));

            let rref = format!("refs/remotes/{}/{}", remote, branch);
            let commit = get_head_commit(&rref);
            let is_merged = match &commit {
                Some(c) => base_commits.iter().any(|bc| is_ancestor(c, bc)),
                None => false,
            };

            let upstream_of = lb_entries.iter().find(|lb| {
                lb.upstream_remote.as_deref() == Some(remote) &&
                lb.upstream_branch.as_deref() == Some(&branch)
            }).map(|lb| lb.name.clone());

            rr_entries.push(RemoteRefEntry {
                remote: remote.clone(),
                branch,
                is_base,
                is_merged,
                upstream_of,
            });
        }
    }

    // Determine what to delete
    // Footnotes: collect unique messages
    let mut footnote_list: Vec<String> = Vec::new();
    let mut get_footnote = |msg: &str, fl: &mut Vec<String>| -> u32 {
        if let Some(pos) = fl.iter().position(|m| m == msg) {
            (pos + 1) as u32
        } else {
            fl.push(msg.to_string());
            fl.len() as u32
        }
    };

    // Local branches: annotation for remain, or mark for delete
    enum LocalAction {
        Remain(String),       // annotation
        DeleteMergedTracking,
        DeleteStray,
        DeleteNonTrackingMerged,
        SkipHead(String),     // annotation when HEAD protection kicks in
    }

    let mut lb_actions: Vec<(String, LocalAction)> = Vec::new();

    for lb in &lb_entries {
        if lb.is_base {
            let stray = lb.upstream_remote.is_some() && !lb.upstream_exists;
            let annotation = if stray { "stray, but: base".to_string() } else { "base".to_string() };
            lb_actions.push((lb.name.clone(), LocalAction::Remain(annotation)));
            continue;
        }

        if let Some(pattern) = glob_matches(&lb.name, &protected) {
            lb_actions.push((lb.name.clone(), LocalAction::Remain(
                format!("merged, but: protected by a pattern `{}`", pattern)
            )));
            continue;
        }

        let has_upstream = lb.upstream_remote.is_some();
        let upstream_gone = has_upstream && !lb.upstream_exists;

        if has_upstream {
            if upstream_gone {
                // Stray
                if raw_specs.contains(&DeleteSpec::Stray) {
                    // Check if HEAD protection needed
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::SkipHead("stray, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteStray));
                    }
                } else {
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(
                        "stray, but: delete range `stray` was not given".to_string()
                    )));
                }
            } else if lb.is_merged {
                // Merged tracking
                if raw_specs.contains(&DeleteSpec::MergedLocal) {
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::SkipHead("merged, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteMergedTracking));
                    }
                } else {
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(
                        "merged, but: delete range `merged-local` was not given".to_string()
                    )));
                }
            } else {
                // Tracking but not merged and not stray - just remain
                lb_actions.push((lb.name.clone(), LocalAction::Remain(String::new())));
            }
        } else {
            // Non-tracking
            if lb.is_merged {
                if raw_specs.contains(&DeleteSpec::Local) {
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::SkipHead("merged, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteNonTrackingMerged));
                    }
                } else {
                    // Footnote
                    let _fn_num = get_footnote(
                        "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.",
                        &mut footnote_list
                    );
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(
                        format!("*{}", _fn_num)
                    )));
                }
            } else {
                // Non-tracking, not merged
                let _fn_num = get_footnote(
                    "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.",
                    &mut footnote_list
                );
                lb_actions.push((lb.name.clone(), LocalAction::Remain(
                    format!("*{}", _fn_num)
                )));
            }
        }
    }

    // Remote refs actions
    enum RemoteAction {
        Remain(String),
        DeleteMergedUpstream,
        DeleteMergedNonUpstream,
    }

    let mut rr_actions: Vec<(String, String, RemoteAction)> = Vec::new(); // (remote, branch, action)

    for rr in &rr_entries {
        if rr.is_base {
            rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain("base".to_string())));
            continue;
        }

        let is_upstream = rr.upstream_of.is_some();

        if rr.is_merged {
            if is_upstream {
                let delete_it = raw_specs.iter().any(|s| matches!(s, DeleteSpec::MergedRemote(r) if r == "*" || r == &rr.remote));
                if delete_it {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::DeleteMergedUpstream));
                } else {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(
                        format!("merged, but: delete range `merged-remote:{}` was not given", rr.remote)
                    )));
                }
            } else {
                // Non-upstream merged
                let delete_it = raw_specs.iter().any(|s| matches!(s, DeleteSpec::Remote(r) if r == "*" || r == &rr.remote));
                if delete_it {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::DeleteMergedNonUpstream));
                } else {
                    let _fn_num = get_footnote(
                        &format!("Make it upstream of a tracking branch or add `--delete 'remote:{}'` flag.", rr.remote),
                        &mut footnote_list
                    );
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(
                        format!("*{}", _fn_num)
                    )));
                }
            }
        } else {
            // Not merged
            if is_upstream {
                rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(String::new())));
            } else {
                // Non-upstream, not merged
                // Check if remote:origin is in delete specs (for "Add --delete 'merged:*' flag" note)
                let has_remote_spec = raw_specs.iter().any(|s| matches!(s, DeleteSpec::Remote(_)));
                if has_remote_spec {
                    let _fn_num = get_footnote(
                        "Add `--delete 'merged:*'` flag.",
                        &mut footnote_list
                    );
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(
                        format!("*{}", _fn_num)
                    )));
                } else {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(String::new())));
                }
            }
        }
    }

    // Collect what will remain and what will be deleted
    let remain_local: Vec<(String, String)> = lb_actions.iter().filter_map(|(name, action)| {
        match action {
            LocalAction::Remain(ann) => Some((name.clone(), ann.clone())),
            LocalAction::SkipHead(ann) => Some((name.clone(), ann.clone())),
            _ => None,
        }
    }).collect();

    let remain_remote: Vec<(String, String)> = rr_actions.iter().filter_map(|(remote, branch, action)| {
        match action {
            RemoteAction::Remain(ann) => Some((format!("{}/{}", remote, branch), ann.clone())),
            _ => None,
        }
    }).collect();

    let delete_merged_tracking: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteMergedTracking) { Some(name.clone()) } else { None }
    }).collect();

    let delete_stray: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteStray) { Some(name.clone()) } else { None }
    }).collect();

    let delete_non_tracking: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteNonTrackingMerged) { Some(name.clone()) } else { None }
    }).collect();

    // Group remote deletes by remote
    let mut delete_remote_upstream: HashMap<String, Vec<String>> = HashMap::new(); // remote -> branches
    let mut delete_remote_non_upstream: HashMap<String, Vec<String>> = HashMap::new();

    for (remote, branch, action) in &rr_actions {
        match action {
            RemoteAction::DeleteMergedUpstream => {
                delete_remote_upstream.entry(remote.clone()).or_default().push(branch.clone());
            }
            RemoteAction::DeleteMergedNonUpstream => {
                delete_remote_non_upstream.entry(remote.clone()).or_default().push(branch.clone());
            }
            _ => {}
        }
    }

    // Check for anything to do
    let has_local_deletes = !delete_merged_tracking.is_empty() 
        || !delete_stray.is_empty() 
        || !delete_non_tracking.is_empty();
    let has_remote_deletes = !delete_remote_upstream.is_empty() 
        || !delete_remote_non_upstream.is_empty();

    // Print "Branches that will remain" section
    println!();
    println!("Branches that will remain:");
    println!("  local branches:");

    for (name, annotation) in &remain_local {
        if annotation.is_empty() {
            println!("    {}", name);
        } else if annotation.starts_with('*') {
            println!("    {} {}", name, annotation);
        } else {
            println!("    {} [{}]", name, annotation);
        }
    }

    println!("  remote references:");

    for (name, annotation) in &remain_remote {
        if annotation.is_empty() {
            println!("    {}", name);
        } else if annotation.starts_with('*') {
            println!("    {} {}", name, annotation);
        } else {
            println!("    {} [{}]", name, annotation);
        }
    }

    // Print footnotes
    if !footnote_list.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        for (i, msg) in footnote_list.iter().enumerate() {
            println!("    *{}: {}", i + 1, msg);
        }
    }

    println!();

    if !has_local_deletes && !has_remote_deletes {
        return Ok(());
    }

    // Print summary of what will be deleted
    // "Delete merged local branches:" section
    let merged_local_all: Vec<&str> = delete_merged_tracking.iter().map(|s| s.as_str())
        .chain(delete_non_tracking.iter().map(|s| s.as_str()))
        .collect();

    if !merged_local_all.is_empty() {
        println!("Delete merged local branches:");
        for name in &delete_merged_tracking {
            println!("  - {}", name);
        }
        for name in &delete_non_tracking {
            println!("  - {} (non-tracking)", name);
        }
    }

    // "Delete merged remote refs:" section
    // Collect all merged remote refs (both upstream and non-upstream)
    // Group by remote for display
    let mut all_remote_deletes: Vec<(String, String, bool)> = Vec::new(); // (remote, branch, is_non_upstream)

    for (remote, branches) in &delete_remote_upstream {
        let mut sorted_branches = branches.clone();
        sorted_branches.sort();
        for b in sorted_branches {
            all_remote_deletes.push((remote.clone(), b, false));
        }
    }
    for (remote, branches) in &delete_remote_non_upstream {
        let mut sorted_branches = branches.clone();
        sorted_branches.sort();
        for b in sorted_branches {
            all_remote_deletes.push((remote.clone(), b, true));
        }
    }
    // Sort by remote, then branch
    all_remote_deletes.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));

    if !all_remote_deletes.is_empty() {
        println!("Delete merged remote refs:");
        for (remote, branch, non_upstream) in &all_remote_deletes {
            if *non_upstream {
                println!("  - {}, refs/heads/{} (non-upstream)", remote, branch);
            } else {
                println!("  - {}, refs/heads/{}", remote, branch);
            }
        }
    }

    if !delete_stray.is_empty() {
        println!("Delete stray local branches:");
        for name in &delete_stray {
            println!("  - {}", name);
        }
    }

    // Confirm if needed
    if !args.dry_run && !no_confirm {
        // Check if stdin/stdout is a terminal
        if !io::stdin().is_terminal() {
            return Err(anyhow!("IO error: not a terminal\n\nCaused by:\n    not a terminal"));
        }

        // Ask confirmation
        let confirmed = dialoguer::Confirm::new()
            .with_prompt("Confirm?")
            .default(false)
            .interact()?;

        if !confirmed {
            println!("Cancelled");
            return Ok(());
        }
    }

    // Execute deletions
    // 1. Remote deletes (all via push --delete)
    // Group by remote
    let mut remote_branches_to_delete: HashMap<String, Vec<String>> = HashMap::new();
    for (remote, branch, _) in &all_remote_deletes {
        remote_branches_to_delete.entry(remote.clone()).or_default().push(branch.clone());
    }

    for (remote, branches) in &remote_branches_to_delete {
        let mut sorted = branches.clone();
        sorted.sort();
        push_delete_remote_branches(remote, &sorted, args.dry_run);
    }

    // 2. Local deletes
    // Order: check if current branch needs detach first
    // Collect all local branches to delete
    let mut all_local_to_delete: Vec<(String, &str)> = Vec::new(); // (name, type: stray/merged/non-tracking)

    for name in &delete_stray {
        all_local_to_delete.push((name.clone(), "stray"));
    }
    for name in &delete_non_tracking {
        all_local_to_delete.push((name.clone(), "non-tracking"));
    }
    for name in &delete_merged_tracking {
        all_local_to_delete.push((name.clone(), "merged"));
    }

    // Sort in reverse alphabetical within each group
    // Actually, from testing, it seems all local branches are deleted in reverse alphabetical order
    // But we need to handle HEAD branch specially (detach first)

    // Sort all_local_to_delete by name in reverse alphabetical
    all_local_to_delete.sort_by(|a, b| b.0.cmp(&a.0));

    // Handle HEAD branch
    let current = current_branch.clone();
    let head_branch_being_deleted = current.as_ref().and_then(|cb| {
        if all_local_to_delete.iter().any(|(n, _)| n == cb) {
            Some(cb.clone())
        } else {
            None
        }
    });

    if let Some(ref head_branch) = head_branch_being_deleted {
        let head_ref = format!("refs/heads/{}", head_branch);
        if args.dry_run {
            detach_head_dry_run(&head_ref);
        } else {
            detach_head_actual(&head_ref);
        }
    }

    // Now delete local branches
    for (name, _) in &all_local_to_delete {
        if args.dry_run {
            println!("Delete branch {} (dry run).", name);
        } else {
            let result = delete_local_branch(name);
            if !result.is_empty() {
                println!("{}", result);
            }
        }
    }

    Ok(())
}

