fn is_terminal_stdin() -> bool {
    use std::os::unix::io::AsRawFd;
    unsafe { libc_isatty(io::stdin().as_raw_fd()) }
}

fn libc_isatty(fd: i32) -> bool {
    // Use a simple syscall check
    // On Linux, we can check /proc/self/fd/<fd> -> /dev/pts/...
    let path = format!("/proc/self/fd/{}", fd);
    if let Ok(target) = std::fs::read_link(&path) {
        let t = target.to_string_lossy();
        return t.starts_with("/dev/pts") || t.starts_with("/dev/tty");
    }
    false
}

fn confirm_interactive() -> Result<bool, String> {
    // Check if stdin is a terminal
    if !is_terminal_stdin() {
        return Err("IO error: not a terminal\n\nCaused by:\n    not a terminal".to_string());
    }

    // Use dialoguer-like output
    // Print: "Confirm? [y/N] " and wait for input
    // With terminal control (hide cursor, etc.)

    // Try to open /dev/tty for terminal interaction
    use std::fs::OpenOptions;
    use std::io::{BufRead, Write};

    let tty_write = OpenOptions::new().write(true).open("/dev/tty");
    let tty_read = OpenOptions::new().read(true).open("/dev/tty");

    if let (Ok(mut tw), Ok(tr)) = (tty_write, tty_read) {
        // Hide cursor
        write!(tw, "\x1b[?25l").ok();
        write!(tw, "\rConfirm? [y/N] ").ok();
        tw.flush().ok();

        // Read a line
        let mut line = String::new();
        let mut reader = std::io::BufReader::new(tr);
        reader.read_line(&mut line).map_err(|e| format!("{}", e))?;
        let trimmed = line.trim().to_lowercase();

        // Show cursor and clear/rewrite line
        let answer = if trimmed == "y" || trimmed == "yes" { "yes" } else { "no" };
        write!(tw, "\x1b[2K\rConfirm? {}\n\x1b[?25h", answer).ok();
        tw.flush().ok();

        Ok(trimmed == "y" || trimmed == "yes")
    } else {
        Err("IO error: not a terminal\n\nCaused by:\n    not a terminal".to_string())
    }
}

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(2);
        }
    };

    match run(args) {
        Ok(()) => {}
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn run(args: Args) -> Result<(), String> {
    // Expand delete specs
    let raw_specs: Vec<DeleteSpec> = if args.delete.is_empty() {
        // Default: merged:origin
        vec![DeleteSpec::MergedLocal, DeleteSpec::MergedRemote("origin".to_string())]
    } else {
        expand_delete_specs(args.delete.clone())
    };

    // Config overrides
    let no_update = args.no_update 
        || git_config_get("trim.update").map(|v| v == "false").unwrap_or(false);
    let no_confirm = args.no_confirm 
        || git_config_get("trim.confirm").map(|v| v == "false").unwrap_or(false);
    let no_detach = args.no_detach 
        || git_config_get("trim.detach").map(|v| v == "false").unwrap_or(false);
    let update_interval: u64 = args.update_interval
        .or_else(|| git_config_get("trim.updateInterval").and_then(|v| v.parse().ok()))
        .unwrap_or(5);

    // Check git repo
    if !git_ok(&["rev-parse", "--git-dir"]) {
        return Err("Not a git repository".to_string());
    }

    // Get remotes
    let remotes = get_remotes();
    if remotes.is_empty() {
        return Err("git-trim requires at least one remote".to_string());
    }

    // Fetch if needed
    if !no_update {
        let should_fetch = if update_interval == 0 {
            true
        } else {
            match seconds_since_last_fetch() {
                Some(secs) => secs >= update_interval,
                None => true,
            }
        };
        if should_fetch {
            do_fetch(&remotes);
        }
    }

    // Determine base branches
    let bases_from_config = args.bases.clone()
        .or_else(|| git_config_get("trim.bases"));

    let base_branches: Vec<String> = if let Some(s) = bases_from_config {
        s.split(',')
            .map(|b| b.trim().to_string())
            .filter(|b| !b.is_empty())
            .collect()
    } else {
        let local_branches = get_local_branches();
        let mut bases = Vec::new();
        for remote in &remotes {
            if let Some(head_branch) = find_remote_head_branch(remote) {
                for lb in &local_branches {
                    if let Some((r, m)) = get_branch_upstream(lb) {
                        if r == *remote && m == head_branch {
                            bases.push(lb.clone());
                            break;
                        }
                    }
                }
            }
        }
        bases
    };

    if base_branches.is_empty() {
        eprintln!("I can't detect base branch! Try following any resolution:");
        eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
        eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
        eprintln!("   to set an upstream branch for <base branch> if exists.");
        eprintln!("You also can set bases manually with any of following commands:");
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
        return Err("No base branch is found!".to_string());
    }

    // Protected patterns
    let protected: Vec<String> = args.protected.clone()
        .or_else(|| git_config_get("trim.protected"))
        .map(|s| s.split(',').map(|p| p.trim().to_string()).filter(|p| !p.is_empty()).collect())
        .unwrap_or_default();

    // Compute base commits and base remote refs
    let mut base_commits: HashSet<String> = HashSet::new();
    let mut base_remote_refs: HashSet<(String, String)> = HashSet::new();

    for base in &base_branches {
        if let Some(commit) = get_head_commit(&format!("refs/heads/{}", base)) {
            base_commits.insert(commit);
        }
        if let Some((remote, branch)) = get_branch_upstream(base) {
            if let Some(commit) = get_head_commit(&format!("refs/remotes/{}/{}", remote, branch)) {
                base_commits.insert(commit);
            }
            base_remote_refs.insert((remote, branch));
        }
    }

    let current_branch = get_current_branch();
    let local_branches = get_local_branches();

    // Build local branch data
    struct LocalEntry {
        name: String,
        upstream_remote: Option<String>,
        upstream_branch: Option<String>,
        upstream_exists: bool,
        is_base: bool,
        is_merged: bool,
        is_current: bool,
    }

    let lb_entries: Vec<LocalEntry> = local_branches.iter().map(|branch| {
        let is_base = base_branches.contains(branch);
        let is_current = current_branch.as_deref() == Some(branch.as_str());

        let (upstream_remote, upstream_branch, upstream_exists) = match get_branch_upstream(branch) {
            Some((remote, branch_name)) => {
                let exists = remote_ref_exists(&remote, &branch_name);
                (Some(remote), Some(branch_name), exists)
            }
            None => (None, None, false),
        };

        let commit = get_head_commit(&format!("refs/heads/{}", branch));
        let is_merged = match &commit {
            Some(c) => base_commits.iter().any(|bc| is_ancestor(c, bc)),
            None => false,
        };

        LocalEntry {
            name: branch.clone(),
            upstream_remote,
            upstream_branch,
            upstream_exists,
            is_base,
            is_merged,
            is_current,
        }
    }).collect();

    // Build remote ref data
    struct RemoteEntry {
        remote: String,
        branch: String,
        is_base: bool,
        is_merged: bool,
        upstream_of: Option<String>,
    }

    let mut rr_entries: Vec<RemoteEntry> = Vec::new();

    for remote in &remotes {
        for branch in get_remote_branches(remote) {
            let is_base = base_remote_refs.contains(&(remote.clone(), branch.clone()));
            let rref = format!("refs/remotes/{}/{}", remote, branch);
            let commit = get_head_commit(&rref);
            let is_merged = match &commit {
                Some(c) => base_commits.iter().any(|bc| is_ancestor(c, bc)),
                None => false,
            };
            let upstream_of = lb_entries.iter().find(|lb| {
                lb.upstream_remote.as_deref() == Some(remote) &&
                lb.upstream_branch.as_deref() == Some(&branch)
            }).map(|lb| lb.name.clone());

            rr_entries.push(RemoteEntry {
                remote: remote.clone(),
                branch,
                is_base,
                is_merged,
                upstream_of,
            });
        }
    }

    // Footnotes
    let mut footnote_list: Vec<String> = Vec::new();

    let mut add_footnote = |msg: &str, fl: &mut Vec<String>| -> u32 {
        if let Some(pos) = fl.iter().position(|m| m == msg) {
            (pos + 1) as u32
        } else {
            fl.push(msg.to_string());
            fl.len() as u32
        }
    };

    // Determine actions for local branches
    #[derive(Debug)]
    enum LocalAction {
        Remain(String),
        DeleteMergedTracking,
        DeleteStray,
        DeleteNonTrackingMerged,
    }

    let mut lb_actions: Vec<(String, LocalAction)> = Vec::new();

    for lb in &lb_entries {
        if lb.is_base {
            let stray = lb.upstream_remote.is_some() && !lb.upstream_exists;
            let ann = if stray { "stray, but: base".to_string() } else { "base".to_string() };
            lb_actions.push((lb.name.clone(), LocalAction::Remain(ann)));
            continue;
        }

        if let Some(pattern) = glob_pattern_matches(&lb.name, &protected) {
            lb_actions.push((lb.name.clone(), LocalAction::Remain(
                format!("merged, but: protected by a pattern `{}`", pattern)
            )));
            continue;
        }

        let has_upstream = lb.upstream_remote.is_some();
        let upstream_gone = has_upstream && !lb.upstream_exists;

        if has_upstream {
            if upstream_gone {
                if raw_specs.contains(&DeleteSpec::Stray) {
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::Remain("stray, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteStray));
                    }
                } else {
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(
                        "stray, but: delete range `stray` was not given".to_string()
                    )));
                }
            } else if lb.is_merged {
                if raw_specs.contains(&DeleteSpec::MergedLocal) {
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::Remain("merged, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteMergedTracking));
                    }
                } else {
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(
                        "merged, but: delete range `merged-local` was not given".to_string()
                    )));
                }
            } else {
                lb_actions.push((lb.name.clone(), LocalAction::Remain(String::new())));
            }
        } else {
            // Non-tracking
            if lb.is_merged {
                if raw_specs.contains(&DeleteSpec::Local) {
                    if lb.is_current && no_detach {
                        lb_actions.push((lb.name.clone(), LocalAction::Remain("merged, but: HEAD".to_string())));
                    } else {
                        lb_actions.push((lb.name.clone(), LocalAction::DeleteNonTrackingMerged));
                    }
                } else {
                    let fn_num = add_footnote(
                        "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.",
                        &mut footnote_list
                    );
                    lb_actions.push((lb.name.clone(), LocalAction::Remain(format!("*{}", fn_num))));
                }
            } else {
                let fn_num = add_footnote(
                    "Set an upstream to make it a tracking branch or add `--delete 'local'` flag.",
                    &mut footnote_list
                );
                lb_actions.push((lb.name.clone(), LocalAction::Remain(format!("*{}", fn_num))));
            }
        }
    }

    // Determine actions for remote refs
    #[derive(Debug)]
    enum RemoteAction {
        Remain(String),
        DeleteMergedUpstream,
        DeleteMergedNonUpstream,
    }

    let mut rr_actions: Vec<(String, String, RemoteAction)> = Vec::new();

    for rr in &rr_entries {
        if rr.is_base {
            rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain("base".to_string())));
            continue;
        }

        let is_upstream = rr.upstream_of.is_some();

        if rr.is_merged {
            if is_upstream {
                let delete_it = raw_specs.iter().any(|s| matches!(s, DeleteSpec::MergedRemote(r) if r == "*" || r == &rr.remote));
                if delete_it {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::DeleteMergedUpstream));
                } else {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(
                        format!("merged, but: delete range `merged-remote:{}` was not given", rr.remote)
                    )));
                }
            } else {
                let delete_it = raw_specs.iter().any(|s| matches!(s, DeleteSpec::Remote(r) if r == "*" || r == &rr.remote));
                if delete_it {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::DeleteMergedNonUpstream));
                } else {
                    let fn_num = add_footnote(
                        &format!("Make it upstream of a tracking branch or add `--delete 'remote:{}'` flag.", rr.remote),
                        &mut footnote_list
                    );
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(format!("*{}", fn_num))));
                }
            }
        } else {
            // Not merged
            if is_upstream {
                rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(String::new())));
            } else {
                // Non-upstream, not merged
                let has_remote_spec = raw_specs.iter().any(|s| matches!(s, DeleteSpec::Remote(_)));
                if has_remote_spec {
                    let fn_num = add_footnote(
                        "Add `--delete 'merged:*'` flag.",
                        &mut footnote_list
                    );
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(format!("*{}", fn_num))));
                } else {
                    rr_actions.push((rr.remote.clone(), rr.branch.clone(), RemoteAction::Remain(String::new())));
                }
            }
        }
    }

    // Collect remain/delete lists
    let remain_local: Vec<(String, String)> = lb_actions.iter().filter_map(|(name, action)| {
        match action {
            LocalAction::Remain(ann) => Some((name.clone(), ann.clone())),
            _ => None,
        }
    }).collect();

    let remain_remote: Vec<(String, String)> = rr_actions.iter().filter_map(|(remote, branch, action)| {
        match action {
            RemoteAction::Remain(ann) => Some((format!("{}/{}", remote, branch), ann.clone())),
            _ => None,
        }
    }).collect();

    let delete_merged_tracking: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteMergedTracking) { Some(name.clone()) } else { None }
    }).collect();

    let delete_stray: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteStray) { Some(name.clone()) } else { None }
    }).collect();

    let delete_non_tracking: Vec<String> = lb_actions.iter().filter_map(|(name, action)| {
        if matches!(action, LocalAction::DeleteNonTrackingMerged) { Some(name.clone()) } else { None }
    }).collect();

    // Group remote deletes by remote (sorted)
    let mut delete_remote_all: Vec<(String, String, bool)> = Vec::new(); // (remote, branch, is_non_upstream)

    for (remote, branch, action) in &rr_actions {
        match action {
            RemoteAction::DeleteMergedUpstream => {
                delete_remote_all.push((remote.clone(), branch.clone(), false));
            }
            RemoteAction::DeleteMergedNonUpstream => {
                delete_remote_all.push((remote.clone(), branch.clone(), true));
            }
            _ => {}
        }
    }
    delete_remote_all.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));

    let has_local_deletes = !delete_merged_tracking.is_empty() 
        || !delete_stray.is_empty() 
        || !delete_non_tracking.is_empty();
    let has_remote_deletes = !delete_remote_all.is_empty();

    // === Print "Branches that will remain" ===
    println!();
    println!("Branches that will remain:");
    println!("  local branches:");

    for (name, ann) in &remain_local {
        if ann.is_empty() {
            println!("    {}", name);
        } else if ann.starts_with('*') {
            println!("    {} {}", name, ann);
        } else {
            println!("    {} [{}]", name, ann);
        }
    }

    println!("  remote references:");

    for (name, ann) in &remain_remote {
        if ann.is_empty() {
            println!("    {}", name);
        } else if ann.starts_with('*') {
            println!("    {} {}", name, ann);
        } else {
            println!("    {} [{}]", name, ann);
        }
    }

    if !footnote_list.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        for (i, msg) in footnote_list.iter().enumerate() {
            println!("    *{}: {}", i + 1, msg);
        }
    }

    println!();

    if !has_local_deletes && !has_remote_deletes {
        return Ok(());
    }

    // === Print deletion summaries ===

    // "Delete merged local branches:" (merged-tracking + non-tracking)
    if !delete_merged_tracking.is_empty() || !delete_non_tracking.is_empty() {
        println!("Delete merged local branches:");
        for name in &delete_merged_tracking {
            println!("  - {}", name);
        }
        for name in &delete_non_tracking {
            println!("  - {} (non-tracking)", name);
        }
    }

    // "Delete merged remote refs:"
    if !delete_remote_all.is_empty() {
        println!("Delete merged remote refs:");
        for (remote, branch, non_upstream) in &delete_remote_all {
            if *non_upstream {
                println!("  - {}, refs/heads/{} (non-upstream)", remote, branch);
            } else {
                println!("  - {}, refs/heads/{}", remote, branch);
            }
        }
    }

    // "Delete stray local branches:"
    if !delete_stray.is_empty() {
        println!("Delete stray local branches:");
        for name in &delete_stray {
            println!("  - {}", name);
        }
    }

    // === Confirm if needed ===
    if !args.dry_run && !no_confirm {
        match confirm_interactive() {
            Ok(true) => {}
            Ok(false) => {
                println!("Cancelled");
                return Ok(());
            }
            Err(e) => return Err(e),
        }
    }

    // === Execute deletions ===

    // 1. Remote deletes - group by remote
    let mut remote_groups: HashMap<String, Vec<String>> = HashMap::new();
    for (remote, branch, _) in &delete_remote_all {
        remote_groups.entry(remote.clone()).or_default().push(branch.clone());
    }

    let mut remote_names: Vec<&String> = remote_groups.keys().collect();
    remote_names.sort();

    for remote in remote_names {
        let mut branches = remote_groups[remote].clone();
        branches.sort();
        push_delete_remote_branches(remote, &branches, args.dry_run);
    }

    // 2. Local deletes
    // Collect all local branches to delete in reverse alphabetical order
    let mut all_local: Vec<(String, &'static str)> = Vec::new();
    for name in &delete_stray {
        all_local.push((name.clone(), "stray"));
    }
    for name in &delete_non_tracking {
        all_local.push((name.clone(), "non-tracking"));
    }
    for name in &delete_merged_tracking {
        all_local.push((name.clone(), "merged-tracking"));
    }

    // Sort by name, reverse alphabetical
    all_local.sort_by(|a, b| b.0.cmp(&a.0));

    // Handle HEAD branch - need to detach first
    let current = current_branch.clone();
    let head_needs_detach = current.as_ref().and_then(|cb| {
        if all_local.iter().any(|(n, _)| n == cb) {
            Some(cb.clone())
        } else {
            None
        }
    });

    if let Some(ref head_branch) = head_needs_detach {
        let head_ref = format!("refs/heads/{}", head_branch);
        if args.dry_run {
            let short = get_short_commit(head_branch).unwrap_or_default();
            let subject = get_commit_subject(head_branch);
            println!("Note: switching to '{}' (dry run)", head_ref);
            println!("You are in 'detached HED' state... blah blah...");
            println!("HEAD is now at {} {} (dry run)", short, subject);
        } else {
            println!("Note: switching to '{}'.", head_ref);
            let output = Command::new("git")
                .args(["checkout", "--detach", head_branch])
                .output();
            match output {
                Ok(o) => {
                    let stderr = String::from_utf8_lossy(&o.stderr);
                    print!("{}", stderr);
                }
                Err(e) => eprintln!("Failed to detach HEAD: {}", e),
            }
        }
    }

    // Delete local branches
    for (name, _) in &all_local {
        if args.dry_run {
            println!("Delete branch {} (dry run).", name);
        } else {
            delete_local_branch_cmd(name);
        }
    }

    Ok(())
}

