use std::collections::{HashMap, HashSet};
use std::io::{self, BufRead, Write};
use std::process::Command;
use std::time::SystemTime;

const VERSION: &str = "0.4.4";

#[derive(Debug, Clone, PartialEq)]
enum DeleteSpec {
    MergedLocal,
    MergedRemote(String),  // remote name or *
    Stray,
    Diverged(String),      // remote name or *
    Local,
    Remote(String),        // remote name or *
}

fn parse_delete_spec(s: &str) -> Result<DeleteSpec, String> {
    match s.trim() {
        "merged-local" => Ok(DeleteSpec::MergedLocal),
        "stray" => Ok(DeleteSpec::Stray),
        "local" => Ok(DeleteSpec::Local),
        other => {
            if let Some(remote) = other.strip_prefix("merged-remote:") {
                Ok(DeleteSpec::MergedRemote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("diverged:") {
                Ok(DeleteSpec::Diverged(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("remote:") {
                Ok(DeleteSpec::Remote(remote.to_string()))
            } else if let Some(remote) = other.strip_prefix("merged:") {
                // Mark as merged:<remote> to expand later
                Ok(DeleteSpec::MergedRemote(format!("\x00merged\x00{}", remote)))
            } else {
                Err(format!("Invalid delete range format `{}`", other))
            }
        }
    }
}

fn expand_delete_specs(specs: Vec<DeleteSpec>) -> Vec<DeleteSpec> {
    let mut result = Vec::new();
    for spec in specs {
        match spec {
            DeleteSpec::MergedRemote(ref s) if s.starts_with('\x00') => {
                let remote = s["\x00merged\x00".len()..].to_string();
                result.push(DeleteSpec::MergedLocal);
                result.push(DeleteSpec::MergedRemote(remote));
            }
            _ => result.push(spec),
        }
    }
    result
}

// Simple glob matching - supports * and ? wildcards (no / crossing)
fn glob_matches(pattern: &str, text: &str) -> bool {
    glob_match_helper(pattern.as_bytes(), text.as_bytes())
}

fn glob_match_helper(pat: &[u8], text: &[u8]) -> bool {
    if pat.is_empty() {
        return text.is_empty();
    }
    if pat[0] == b'*' {
        // Skip multiple * 
        let pat = &pat[1..];
        if pat.is_empty() {
            return true;
        }
        for i in 0..=text.len() {
            if glob_match_helper(pat, &text[i..]) {
                return true;
            }
        }
        return false;
    }
    if text.is_empty() {
        return false;
    }
    if pat[0] == b'?' || pat[0] == text[0] {
        return glob_match_helper(&pat[1..], &text[1..]);
    }
    false
}

fn glob_pattern_matches(name: &str, patterns: &[String]) -> Option<String> {
    for p in patterns {
        if glob_matches(p, name) {
            return Some(p.clone());
        }
    }
    None
}

struct Args {
    bases: Option<String>,
    protected: Option<String>,
    no_update: bool,
    update_interval: Option<u64>,
    no_confirm: bool,
    no_detach: bool,
    delete: Vec<DeleteSpec>,
    dry_run: bool,
}

fn print_help_long() {
    println!("Automatically trims your tracking branches whose upstream branches are merged or stray.");
    println!("`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.");
    println!();
    println!("Usage: git-trim [OPTIONS]");
    println!();
    println!("Options:");
    println!("  -b, --bases <BASES>");
    println!("          Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]");
    println!("          ");
    println!("          The default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.");
    println!();
