    println!();
    println!("Usage: git-trim [OPTIONS]");
    println!();
    println!("Options:");
    println!("  -b, --bases <BASES>          Comma separated multiple names of branches [config: trim.bases]");
    println!("  -p, --protected <PROTECTED>  Comma separated multiple glob patterns [config: trim.protected]");
    println!("      --no-update              Do not update remotes [config: trim.update]");
    println!("      --update-interval <UPDATE_INTERVAL>");
    println!("                               Prevents too frequent updates [default: 5] [config: trim.updateInterval]");
    println!("      --no-confirm             Do not ask confirm [config: trim.confirm]");
    println!("      --no-detach              Do not detach when HEAD is about to be deleted [config: trim.detach]");
    println!("  -d, --delete <DELETE>        Comma separated values of delete ranges [default : `merged:origin`] [config: trim.delete]");
    println!("      --dry-run                Do not delete branches, show what branches will be deleted");
