fn parse_args() -> Result<Args, String> {
    let raw_args: Vec<String> = std::env::args().collect();

    let mut bases: Option<String> = None;
    let mut protected: Option<String> = None;
    let mut no_update = false;
    let mut update_interval: Option<u64> = None;
    let mut no_confirm = false;
    let mut no_detach = false;
    let mut delete_specs: Vec<DeleteSpec> = Vec::new();
    let mut dry_run = false;

    let mut i = 1;
    while i < raw_args.len() {
        let arg = raw_args[i].as_str();
        match arg {
            "-h" => {
                print_help_short();
                std::process::exit(0);
            }
            "--help" => {
                print_help_long();
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("git-trim {}", VERSION);
                std::process::exit(0);
            }
            "--dry-run" => { dry_run = true; }
            "--no-update" => { no_update = true; }
            "--no-confirm" => { no_confirm = true; }
            "--no-detach" => { no_detach = true; }
            "-b" | "--bases" => {
                i += 1;
                if i >= raw_args.len() {
                    return Err("--bases requires an argument".to_string());
                }
                bases = Some(raw_args[i].clone());
            }
            "-p" | "--protected" => {
                i += 1;
                if i >= raw_args.len() {
                    return Err("--protected requires an argument".to_string());
                }
                protected = Some(raw_args[i].clone());
            }
            "--update-interval" => {
                i += 1;
                if i >= raw_args.len() {
                    return Err("--update-interval requires an argument".to_string());
                }
                update_interval = Some(raw_args[i].parse().map_err(|_| "invalid update-interval".to_string())?);
            }
            "-d" | "--delete" => {
                i += 1;
                if i >= raw_args.len() {
                    return Err("--delete requires an argument".to_string());
                }
                for part in raw_args[i].split(',') {
                    let part = part.trim();
                    if part.is_empty() { continue; }
                    match parse_delete_spec(part) {
                        Ok(spec) => delete_specs.push(spec),
                        Err(e) => return Err(format!(
                            "error: invalid value \'{}\' for \'--delete <DELETE>\': {}\n\nFor more information, try \'--help\'.",
                            part, e
                        )),
                    }
                }
            }
            _ => {
                // Handle --key=value style
                if let Some(val) = arg.strip_prefix("--bases=").or_else(|| arg.strip_prefix("-b=")) {
                    bases = Some(val.to_string());
                } else if let Some(val) = arg.strip_prefix("--protected=").or_else(|| arg.strip_prefix("-p=")) {
                    protected = Some(val.to_string());
                } else if let Some(val) = arg.strip_prefix("--update-interval=") {
                    update_interval = Some(val.parse().map_err(|_| "invalid update-interval".to_string())?);
                } else if let Some(val) = arg.strip_prefix("--delete=").or_else(|| arg.strip_prefix("-d=")) {
                    for part in val.split(',') {
                        let part = part.trim();
                        if part.is_empty() { continue; }
                        match parse_delete_spec(part) {
                            Ok(spec) => delete_specs.push(spec),
                            Err(e) => return Err(format!(
                                "error: invalid value \'{}\' for \'--delete <DELETE>\': {}\n\nFor more information, try \'--help\'.",
                                part, e
                            )),
                        }
                    }
                } else {
                    return Err(format!(
                        "error: unexpected argument \'{}\' found\n\nUsage: git-trim [OPTIONS]\n\nFor more information, try \'--help\'.",
                        arg
                    ));
                }
            }
        }
        i += 1;
    }

    Ok(Args {
        bases,
        protected,
        no_update,
        update_interval,
        no_confirm,
        no_detach,
        delete: delete_specs,
        dry_run,
    })
}

fn git_config_get(key: &str) -> Option<String> {
    let output = Command::new("git")
        .args(["config", "--get", key])
        .output()
        .ok()?;
    if output.status.success() {
        let s = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if s.is_empty() { None } else { Some(s) }
    } else {
        None
    }
}

fn git_ok(args: &[&str]) -> bool {
