            }
            "-d" | "--delete" => {
                i += 1;
                if i >= raw_args.len() {
                    return Err("--delete requires an argument".to_string());
                }
                for part in raw_args[i].split(',') {
                    let part = part.trim();
                    if part.is_empty() { continue; }
                    match parse_delete_spec(part) {
                        Ok(spec) => delete_specs.push(spec),
                        Err(e) => return Err(format!(
                            "error: invalid value \'{}\' for \'--delete <DELETE>\': {}\n\nFor more information, try \'--help\'.",
                            part, e
                        )),
                    }
                }
            }
            _ => {
                // Handle --key=value style
                if let Some(val) = arg.strip_prefix("--bases=").or_else(|| arg.strip_prefix("-b=")) {
                    bases = Some(val.to_string());
                } else if let Some(val) = arg.strip_prefix("--protected=").or_else(|| arg.strip_prefix("-p=")) {
                    protected = Some(val.to_string());
                } else if let Some(val) = arg.strip_prefix("--update-interval=") {
