fn is_stdin_terminal() -> bool {
    let path = "/proc/self/fd/0";
    if let Ok(target) = std::fs::read_link(path) {
        let t = target.to_string_lossy();
        return t.starts_with("/dev/pts") || t.starts_with("/dev/tty");
    }
    false
}

fn confirm_interactive() -> Result<bool, String> {
    if !is_stdin_terminal() {
        return Err("IO error: not a terminal\n\nCaused by:\n    not a terminal".to_string());
    }

    let tty_path = "/dev/tty";
    let mut tty = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(tty_path)
        .map_err(|e| format!("IO error: {}", e))?;

    write!(tty, "\x1b[?25l").ok();
    write!(tty, "Confirm? [y/N] ").ok();
    tty.flush().ok();

    let mut buf = [0u8; 256];
    let n = {
        use std::io::Read;
        tty.read(&mut buf).map_err(|e| format!("IO error: {}", e))?
    };
    let input = String::from_utf8_lossy(&buf[..n]);
    let trimmed = input.trim().to_lowercase();

    let answer = if trimmed == "y" || trimmed == "yes" { "yes" } else { "no" };
    write!(tty, "\x1b[2K\rConfirm? {}\n\x1b[?25h", answer).ok();
    tty.flush().ok();

    Ok(trimmed == "y" || trimmed == "yes")
}

